def print_chunks(text, chunk_size=10):
    i = 0
    while i < len(text):

        current_chunk_size = chunk_size + random.randint(-3, 3)
        current_chunk_size = max(2, current_chunk_size)
        
        chunk = text[i:i + current_chunk_size]
        
        sys.stdout.write(chunk)
        sys.stdout.flush()
        
        i += current_chunk_size
        

        time.sleep(random.uniform(0.04, 0.18))
    
    print() 

if __name__ == "__main__":

    simulate_java_bugs()

